  "{n} tracks": { ca: "{n} pistes", es: "{n} pistas" },
  "Auto Key is off: every key of {c} moved with it. Turn on Auto Key (N) to key a pose, or Ctrl+Z.": { ca: "Auto Key està desactivat: totes les claus de {c} s’han mogut amb el canvi. Activa Auto Key (N) per gravar una pose, o Ctrl+Z.", es: "Auto Key está desactivado: todas las claves de {c} se han movido con el cambio. Activa Auto Key (N) para grabar una pose, o Ctrl+Z." },
  "Changed {c} (no animation: Auto Key is off).": { ca: "Canviat {c} (sense animació: Auto Key està desactivat).", es: "Cambiado {c} (sin animación: Auto Key está desactivado)." },
  "Select a control first (ctrl_pilota, ctrl_top…).": { ca: "Primer selecciona un control (ctrl_pilota, ctrl_top…).", es: "Primero selecciona un control (ctrl_pilota, ctrl_top…)." },
  "{h} has no animated {g} tracks yet: change it first, or use Auto Key.": { ca: "{h} encara no té pistes {g} animades: canvia-les primer, o fes servir Auto Key.", es: "{h} aún no tiene pistas {g} animadas: cámbialas primero, o usa Auto Key." },
  "Select a control first.": { ca: "Primer selecciona un control.", es: "Primero selecciona un control." },
