  'Helpers are hidden: press Shift+H to show them.': { ca: 'Els helpers estan ocults: prem Maj+H per mostrar-los.', es: 'Los helpers están ocultos: pulsa Mayús+H para mostrarlos.' },
  'Set Keys works in Set Key Mode: press \' or the Set K. button.': { ca: 'Set Keys funciona en Set Key Mode: prem \' o el botó Set K.', es: 'Set Keys funciona en Set Key Mode: pulsa \' o el botón Set K.' },
  'Key Mode: , and . jump from key to key.': { ca: 'Key Mode: , i . salten de clau en clau.', es: 'Key Mode: , y . saltan de clave en clave.' },
  'Key Mode off: , and . move one frame.': { ca: 'Key Mode desactivat: , i . avancen un fotograma.', es: 'Key Mode desactivado: , y . avanzan un fotograma.' },
  'Ball_01 is linked to the helpers: animate the helpers instead. Root is selected.': { ca: 'Ball_01 està enllaçada als helpers: anima els helpers. S’ha seleccionat Root.', es: 'Ball_01 está vinculada a los helpers: anima los helpers. Se ha seleccionado Root.' },
  'Select All: in this lab, select one helper at a time.': { ca: 'Select All: en aquest lab, selecciona els helpers d’un en un.', es: 'Select All: en este lab, selecciona los helpers de uno en uno.' },
  'Y is the depth of this side view: the rig does not move in Y.': { ca: 'Y és la profunditat d’aquesta vista lateral: el rig no es mou en Y.', es: 'Y es la profundidad de esta vista lateral: el rig no se mueve en Y.' },
  'Orbit: Alt + middle mouse button drag in the viewport.': { ca: 'Orbit: arrossega amb Alt + botó central al viewport.', es: 'Orbit: arrastra con Alt + botón central en el viewport.' },
